css:
.di-print {
	font-family: Arial, sans-serif;
	font-size: 11px;
	line-height: 1.4;
}

.di-print table {
	width: 100%;
	border-collapse: collapse;
}

.di-print th,
.di-print td {
	border: 1px solid #333;
	padding: 4px 6px;
	text-align: left;
}

.di-print th {
	background: #f5f5f5;
	font-weight: bold;
}

.di-header {
	text-align: center;
	margin-bottom: 10px;
}

.di-header h2 {
	margin: 0;
	font-size: 16px;
}

.di-info-table td {
	border: none;
	padding: 2px 6px;
	vertical-align: top;
}

.di-info-table .label-col {
	font-weight: bold;
	width: 140px;
	white-space: nowrap;
}

.di-totals td {
	text-align: right;
	font-weight: bold;
}

.di-fbr-section {
	margin-top: 15px;
	padding: 10px;
	border: 1px solid #333;
	display: flex;
	align-items: center;
	gap: 15px;
}

.di-qr-code {
	width: 96px;
	height: 96px;
}

.di-fbr-info {
	flex: 1;
	font-size: 10px;
}

.di-right {
	text-align: right;
}

.di-center {
	text-align: center;
}
